use std::{sync::mpsc,time::Duration};
use maho_omo_task::{timers::HostTimers,status_ui::StatusUiTimers};
#[test] fn due_callback_fires_once_through_completion_signal() { let timers=HostTimers::default(); let (sender,receiver)=mpsc::channel(); timers.set(Box::new(move || sender.send("fired").expect("signal")),0); assert_eq!(receiver.recv_timeout(Duration::from_secs(5)).expect("timer callback"),"fired"); assert!(matches!(receiver.recv_timeout(Duration::from_secs(5)),Err(mpsc::RecvTimeoutError::Disconnected))); }
#[test] fn clearing_timer_drops_callback_without_waiting_for_deadline() { let timers=HostTimers::default(); let (sender,receiver)=mpsc::channel::<()>(); let handle=timers.set(Box::new(move || { sender.send(()).expect("unexpected callback"); }),60000); timers.clear(handle); assert!(matches!(receiver.recv_timeout(Duration::from_secs(5)),Err(mpsc::RecvTimeoutError::Disconnected))); timers.clear(handle); }
#[test] fn dropping_host_cancels_pending_callbacks() { let timers=HostTimers::default(); let (sender,receiver)=mpsc::channel::<()>(); timers.set(Box::new(move || { sender.send(()).expect("unexpected callback"); }),60000); drop(timers); assert!(matches!(receiver.recv_timeout(Duration::from_secs(5)),Err(mpsc::RecvTimeoutError::Disconnected))); }
